import java.util.*;

class Solution {
    public int maxAbsoluteSum(int[] moves) {
        int sum = 0, maxP = 0, minP = 0; // 0 = empty prefix
        for (int x : moves) {
            sum += x;
            maxP = Math.max(maxP, sum);
            minP = Math.min(minP, sum);
        }
        return maxP - minP; // largest gap between two prefix sums
    }
}

