function maxAbsoluteSum(a) {
  let best = 0, cmax = 0, cmin = 0;
  for (const x of a) { cmax = Math.max(0, cmax + x); cmin = Math.min(0, cmin + x); best = Math.max(best, cmax, -cmin); }
  return best;
}
